}

.post-header {
  border-left: 0.4rem solid var(--accent);
  padding-left: 1rem;
  margin-bottom: 1.8rem;
}

.post-header h1 {
  font-family: "Fraunces", Georgia, serif;
  font-size: clamp(1.8rem, 4.5vw, 2.4rem);
  font-weight: 800;
  line-height: 1.12;
  letter-spacing: -0.015em;
  margin: 0 0 0.35rem;
}

.post-header time {
  display: inline-block;
}

.post-body {
  font-size: 1.08rem;
  min-width: 0;
}

.post-body > :first-child {
  margin-top: 0;
}

.post-body > :last-child {
  margin-bottom: 0;
}

.post-body p {
  margin: 0 0 1.2rem;
}

.post-body h2 {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.48rem;
  line-height: 1.22;
  margin: 2.2rem 0 0.7rem;
}

.post-body h3 {
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.2rem;
  line-height: 1.28;
  margin: 1.8rem 0 0.6rem;
}

.post-body h4 {
  font-size: 1.04rem;
  font-weight: 700;
  margin: 1.5rem 0 0.5rem;
}

.post-body ul,
.post-body ol {
  margin: 0 0 1.2rem;
  padding-left: 1.4rem;
}

.post-body li {
  margin: 0.35rem 0;
}

.post-body li::marker {
  color: var(--accent);
}

.post-body blockquote {
  margin: 1.4rem 0;
  padding: 0.75rem 1.1rem;
  border-left: 0.35rem solid var(--accent);
  background: var(--accent-soft);
  border-radius: 0 0.6rem 0.6rem 0;
}

.post-body blockquote > :first-child {
  margin-top: 0;
}

.post-body blockquote > :last-child {
  margin-bottom: 0;
}

.post-body pre {
  overflow-x: auto;
  max-width: 100%;
  margin: 1.4rem 0;
  padding: 0.9rem 1rem;
  border: 1px solid var(--line);
  border-radius: 0.6rem;
  background: var(--code-bg);
  font-size: 0.88rem;
  line-height: 1.6;
}

.post-body code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  font-size: 0.92em;
  background: var(--code-bg);
  border: 1px solid var(--line);
  border-radius: 0.3rem;
  padding: 0.08rem 0.3rem;
}

.post-body pre code {
  background: transparent;
  border: 0;
  padding: 0;
  font-size: 1em;
}

.post-body hr {
  border: 0;
  border-top: 1px solid var(--line);
  margin: 2rem 0;
}

.post-body a {
  color: var(--accent);
}

.notice {
  color: var(--fg);
  background: var(--accent-soft);
  border: 1px solid var(--line);
  border-left: 0.35rem solid var(--accent);
  border-radius: 0.6rem;
  padding: 0.85rem 1rem;
  margin: 1.6rem 0 0;
  font-style: normal;
}

.receipt {
  margin: 2.5rem 0 0;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--muted);
}

.receipt a {
  color: var(--accent);
}

.colophon {
  border-top: 1px solid var(--line);
  padding-top: 1rem;
  padding-bottom: 3rem;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 0.82rem;
  line-height: 1.5;
  color: var(--muted);
}

.colophon p {
  margin: 0;
}

@media (max-width: 640px) {
  body {
    font-size: 1rem;
  }

  .masthead,
  main,
  .colophon {
    padding-left: 0.9rem;
    padding-right: 0.9rem;
  }

  .masthead {
    padding-top: 2.1rem;
  }

  .strip {
    padding-left: 0.9rem;
    padding-right: 0.9rem;
  }

  .about {
    padding: 1rem;
    border-radius: 0.7rem;
  }

  .post-header {
    padding-left: 0.85rem;
  }

  .post-body {
    font-size: 1.02rem;
  }
}

